import {escapeHtml as e} from './domain.js';
import {makePdf,stampMaterial} from './pdf-export.js';
import {methodConfig,blockDay} from './study-method.js';
import {syllabusKey} from './cycle-plan.js';
import {durationText,planLabel,flashScore} from './study-state.js';
export function createExports({state,api,notify,admin,premium,filteredLogs}){
 let url=null;
 const data=t=>state.data[t]||[];
 function present(bytes,title){if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));document.querySelector('#export-dialog')?.remove();const el=document.createElement('dialog');el.id='export-dialog';el.className='study-dialog';el.innerHTML=`<header class="dialog-header"><h2>${e(title)}</h2><button data-action="export-close">Fechar</button></header><div id="dialog-notice" role="status"></div><div class="dialog-body"><p>Marca d’água aplicada em todas as páginas.</p><div class="actions"><a class="btn primary" href="${url}" download="${e(title.replace(/[^\p{L}\d -]/gu,'').slice(0,100))}.pdf">Baixar PDF</a><a class="btn" href="${url}" target="_blank" rel="noopener">Abrir PDF para imprimir</a></div><iframe class="pdf-preview" src="${url}" title="Prévia do PDF"></iframe></div>`;document.body.append(el);el.showModal?.();if(!el.showModal)el.setAttribute('open','');notify('PDF preparado com marca d’água.');}
 function student(){return admin()?(data('profiles').find(p=>p.id===state.filter.student_id)||data('profiles').find(p=>p.role!=='admin')):state.profile;}
 function cycleModel(c){const who=data('profiles').find(p=>p.id===c.student_id);return {title:c.title,subtitle:(who?.name||'')+' · '+(who?.career||'')+' · '+c.notes,sections:[...new Set(c.blocks.map(b=>blockDay(b,c)))].sort((a,b)=>a-b).map(day=>({title:planLabel(day),lines:c.blocks.filter(b=>blockDay(b,c)===day).flatMap(b=>{const cfg=methodConfig(b.method),s=data('method_studies').find(s=>s.cycle_id===c.id&&s.block_id===b.id);return [b.subject+' · '+b.topic,'Planejado: '+b.minutes+' minutos · Prioridade: '+cfg.priority,...cfg.steps.filter(st=>st.kind!=='flashcard'||day>=8).map((st,i)=>`${s?.flags?.[st.id]?'[x]':'[ ]'} Etapa ${i+1}: ${st.title}`),'Questões iniciais: '+cfg.initial_questions,'Revisões: '+cfg.reviews.map(r=>'+'+r.after+' dias / '+r.questions+' questões').join('; '),...(cfg.notes||b.notes?['Orientação: '+cfg.notes+' '+b.notes]:[]),...[cfg.resource_id,cfg.video_id].map(id=>data('resources').find(r=>r.id===id)).filter(Boolean).map(r=>'Conteúdo recomendado: '+r.title)];})}))};}
 function syllabusModel(p){const topics=state.topics.filter(t=>t.career===p.career);return {title:'Edital verticalizado · '+p.career,subtitle:p.name,sections:[...new Set(topics.map(t=>t.subject))].map(subject=>({title:subject,lines:topics.filter(t=>t.subject===subject).map(t=>{const f=data('progress').find(x=>x.student_id===p.id&&x.key==='edital|'+syllabusKey(t))?.flags||{};return t.code+' · '+t.title+'\n'+[['study','Estudo'],['questions','Questões'],['summary','Resumo'],['review','Revisão'],['flashcards','Flashcards']].map(([k,n])=>(f[k]?'[x] ':'[ ] ')+n).join(' | ');})}))};}
 function reportModel(){const rows=filteredLogs(),uid=state.filter.student_id||(!admin()?state.profile.id:null),runs=data('flashcard_runs').filter(r=>!uid||r.student_id===uid),cards=flashScore(runs);return {title:'Relatório de desempenho',subtitle:(uid?data('profiles').find(p=>p.id===uid)?.name:'Todos os alunos')+' · '+(state.filter.period||'Todo o histórico'),sections:[{title:'Resultados',lines:[rows.reduce((a,l)=>a+l.total,0)+' questões · '+rows.reduce((a,l)=>a+l.correct,0)+' acertos','Tempo estudado: '+durationText(rows.reduce((a,l)=>a+Number(l.minutes),0)*60),`Flashcards (histórico completo): ${cards.correct} acertos, ${cards.wrong} erros, ${cards.forgot} não lembrados`]},...rows.map(l=>({title:l.date+' · '+l.subject+' · '+l.topic,lines:[...(admin()?[data('profiles').find(p=>p.id===l.student_id)?.name||'']:[]),`${l.total} questões · ${l.correct} acertos · ${l.total-l.correct} erros · ${durationText(Number(l.minutes)*60)}`,l.source,l.notes||'']}))]};}
 function controls(){const names={edital:'Exportar edital',panorama:'Exportar panorama',desempenho:'Exportar relatório',registros:'Exportar registros',erros:'Exportar caderno',questoes:'Exportar lista de questões'};const heading=document.querySelector('#content .heading');if(names[state.view]&&heading){const b=document.createElement('button');b.dataset.action='export-page';b.textContent=names[state.view];heading.append(b);}if(state.view==='ciclos'){for(const c of data('cycles').filter(c=>admin()||c.student_id===state.profile.id)){const target=admin()?document.querySelector(`[data-action="edit-cycle"][data-id="${c.id}"]`)?.parentElement:heading;if(!target)continue;const b=document.createElement('button');b.dataset.action='export-cycle';b.dataset.id=c.id;b.textContent='Exportar '+c.title;target.append(b);}}}
 async function click(el){const a=el.dataset.action;if(a==='export-close'){document.querySelector('#export-dialog')?.remove();if(url)URL.revokeObjectURL(url);url=null;notify('Prévia fechada.','info');return true;}
 if(a==='print-exam'){const p=await api.rpc('get_exam_print',{eid:el.dataset.id});const model={title:p.exam.title+' · '+(p.exam.career||''),subtitle:(p.exam.description||'')+' · '+p.exam.duration+' minutos',sections:[{title:'Identificação',lines:['Nome: ____________________________________________________']},...p.questions.map((q,i)=>({title:'Questão '+(i+1)+' · '+q.subject,lines:[q.body,...q.options.map((o,n)=>String.fromCharCode(65+n)+') '+o)]})),{title:'Gabarito comentado',breakBefore:true,lines:[]},...p.questions.map((q,i)=>({title:'Questão '+(i+1)+' · '+String.fromCharCode(65+q.correct_index),lines:[q.explanation]}))]};present(await makePdf(model),p.exam.title);return true;}
 if(a==='export-cycle'){const c=data('cycles').find(c=>c.id===el.dataset.id);if(!c)throw Error('Ciclo não encontrado.');present(await makePdf(cycleModel(c)),c.title);return true;}
 if(a==='export-material'||a==='open-resource'){const r=data('resources').find(r=>r.id===el.dataset.id);if(!r)throw Error('Material não encontrado.');if(r.kind==='Vídeo')return false;const source=r.storage_path?await api.assetUrl(r.storage_path):r.url;let response;try{response=await fetch(source);}catch{throw Error('O servidor desse link não permite preparar o PDF. Peça ao mentor para enviar o arquivo diretamente na plataforma.');}if(!response.ok)throw Error('Não foi possível abrir o material.');const bytes=new Uint8Array(await response.arrayBuffer());present(await stampMaterial(bytes,response.headers.get('content-type')||''),r.title);await api.save('resource_views',{student_id:state.profile.id,resource_id:r.id});return true;}
 if(a!=='export-page')return false;let model;if(['edital','panorama'].includes(state.view)){const p=student();if(!p)throw Error('Selecione um aluno.');model=syllabusModel(p);}else if(state.view==='erros'){model={title:'Caderno de erros',sections:data('errors').filter(x=>(!state.filter.subject||x.subject.toLowerCase().includes(state.filter.subject.toLowerCase()))&&(!state.filter.topic||x.topic.toLowerCase().includes(state.filter.topic.toLowerCase()))&&(!state.filter.reason||x.reason===state.filter.reason)).map(x=>({title:x.subject+' · '+x.topic,lines:[x.reason,x.body,x.explanation,x.source]}))};}else if(state.view==='questoes'){model={title:'Lista de questões',sections:data('questions').filter(q=>(!state.filter.subject||q.subject.toLowerCase().includes(state.filter.subject.toLowerCase()))&&(!state.filter.topic||q.topic.toLowerCase().includes(state.filter.topic.toLowerCase()))).map((q,i)=>({title:'Questão '+(i+1)+' · '+q.subject,lines:[q.body,...q.options.map((o,n)=>String.fromCharCode(65+n)+') '+o)]}))};}else model=reportModel();present(await makePdf(model),model.title);return true;}
 return {controls,click,cycleModel,syllabusModel,reportModel};
}
